describe('Multi-step Form Navigation', () => {
    beforeEach(() => {
        cy.visit('/multi-step-form');
    });

    it('should retain data when navigating back to a previous step', () => {
        // Fill out the first step
        cy.get('input[name="firstName"]').type('John');
        cy.get('input[name="lastName"]').type('Doe');
        cy.get('button.next').click();

        // Fill out the second step
        cy.get('input[name="email"]').type('john.doe@example.com');
        cy.get('button.prev').click(); // Go back to the first step

        // Verify that the first step data is still present
        cy.get('input[name="firstName"]').should('have.value', 'John');
        cy.get('input[name="lastName"]').should('have.value', 'Doe');
    });

    it('should not retain data if the form is reset', () => {
        // Fill out the first step
        cy.get('input[name="firstName"]').type('Jane');
        cy.get('input[name="lastName"]').type('Smith');
        cy.get('button.next').click();

        // Reset the form
        cy.get('button.reset').click();

        // Verify that the first step data is cleared
        cy.get('input[name="firstName"]').should('have.value', '');
        cy.get('input[name="lastName"]').should('have.value', '');
    });
});
